namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_FirstPage_HasCorrectProperties()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(10, result.Count);
        Assert.False(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_MiddlePage_HasBothNavigation()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(10, result.Count);
        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
    }

    [Fact]
    public void Create_LastPage_HasPartialItems()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 3, 10);

        // Assert
        Assert.Equal(3, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Equal(5, result.Count);
        Assert.True(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void Create_EmptySource_HasNoPages()
    {
        // Arrange
        var source = Enumerable.Empty<int>().AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(0, result.TotalPages);
        Assert.Empty(result);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_SinglePage_NoPagination()
    {
        // Arrange
        var source = Enumerable.Range(1, 5).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(1, result.TotalPages);
        Assert.Equal(5, result.Count);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_ExactlyOnePage_NoPagination()
    {
        // Arrange
        var source = Enumerable.Range(1, 10).AsQueryable();

        // Act
        var result = PaginatedList<int>.Create(source, 1, 10);

        // Assert
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(1, result.TotalPages);
        Assert.Equal(10, result.Count);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_PageSizeOne_ManyPages()
    {
        // Arrange
        var source = Enumerable.Range(1, 3).AsQueryable();

        // Act
        var page1 = PaginatedList<int>.Create(source, 1, 1);
        var page2 = PaginatedList<int>.Create(source, 2, 1);
        var page3 = PaginatedList<int>.Create(source, 3, 1);

        // Assert
        Assert.Equal(3, page1.TotalPages);
        Assert.Single(page1);
        Assert.Equal(1, page1[0]);

        Assert.Single(page2);
        Assert.Equal(2, page2[0]);

        Assert.Single(page3);
        Assert.Equal(3, page3[0]);
        Assert.False(page3.HasNextPage);
    }

    [Fact]
    public void Constructor_ComputesTotalPagesCorrectly()
    {
        // 11 items, page size 5 => ceil(11/5) = 3
        var list = new PaginatedList<string>(new List<string> { "a", "b" }, 11, 2, 5);
        Assert.Equal(3, list.TotalPages);
        Assert.Equal(2, list.PageIndex);
        Assert.Equal(2, list.Count);
    }

    [Fact]
    public void Create_WithStrings_ReturnsCorrectItems()
    {
        // Arrange
        var source = new[] { "Alpha", "Beta", "Charlie", "Delta", "Echo" }.AsQueryable();

        // Act
        var result = PaginatedList<string>.Create(source, 1, 3);

        // Assert
        Assert.Equal(3, result.Count);
        Assert.Equal("Alpha", result[0]);
        Assert.Equal("Beta", result[1]);
        Assert.Equal("Charlie", result[2]);
        Assert.Equal(2, result.TotalPages);
        Assert.True(result.HasNextPage);
    }
}

