using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class HomeControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly HomeController _controller;

    public HomeControllerTests()
    {
        _context = TestDbContextFactory.Create(nameof(HomeControllerTests) + Guid.NewGuid());
        _controller = new HomeController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        // Act
        var result = _controller.Index();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Null(viewResult.ViewName);
    }

    [Fact]
    public void Contact_ReturnsViewWithMessage()
    {
        // Act
        var result = _controller.Contact();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("Your contact page.", _controller.ViewBag.Message);
    }

    [Fact]
    public void Error_ReturnsViewResult()
    {
        // Act
        var result = _controller.Error();

        // Assert
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Unauthorized_ReturnsViewWithPermissionMessage()
    {
        // Act
        var result = _controller.Unauthorized();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
    }

    [Fact]
    public void About_NoStudents_ReturnsEmptyList()
    {
        // Act
        var result = _controller.About();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void About_WithStudents_GroupsByEnrollmentDate()
    {
        // Arrange
        var date1 = new DateTime(2023, 9, 1);
        var date2 = new DateTime(2024, 1, 15);
        _context.Students.AddRange(
            new Student { LastName = "A", FirstMidName = "X", EnrollmentDate = date1 },
            new Student { LastName = "B", FirstMidName = "Y", EnrollmentDate = date1 },
            new Student { LastName = "C", FirstMidName = "Z", EnrollmentDate = date2 }
        );
        _context.SaveChanges();

        // Act
        var result = _controller.About();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Equal(2, model.Count);

        var group1 = model.Single(g => g.EnrollmentDate == date1);
        Assert.Equal(2, group1.StudentCount);

        var group2 = model.Single(g => g.EnrollmentDate == date2);
        Assert.Equal(1, group2.StudentCount);
    }
}

