using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create(nameof(StudentsControllerTests) + Guid.NewGuid());
        _controller = new StudentsController(_context);
        // Drain static notification queue
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
    }

    private Student SeedStudent(string lastName = "Doe", string firstName = "John", DateTime? enrollmentDate = null)
    {
        var student = new Student
        {
            LastName = lastName,
            FirstMidName = firstName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { LastName = "Adams", FirstMidName = "Alice", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { LastName = "Baker", FirstMidName = "Bob", EnrollmentDate = new DateTime(2024, 1, 15) },
            new Student { LastName = "Clark", FirstMidName = "Charlie", EnrollmentDate = new DateTime(2023, 9, 1) },
            new Student { LastName = "Davis", FirstMidName = "Diana", EnrollmentDate = new DateTime(2024, 1, 15) }
        );
        _context.SaveChanges();
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index(null, null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal(4, model.Count);
        Assert.Equal("Adams", model[0].LastName);
        Assert.Equal("Baker", model[1].LastName);
        Assert.Equal("Clark", model[2].LastName);
        Assert.Equal("Davis", model[3].LastName);
    }

    [Fact]
    public void Index_NameDesc_OrdersByLastNameDescending()
    {
        // Arrange
        SeedStudents();

        // Act
        var result = _controller.Index("name_desc", null, null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<PaginatedList<Student>>(viewResult.Model);
        Assert.Equal("Davis", model[0].LastName);
        Assert.Equal("Clark", model[1].LastName);
    }

