        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void CreatePost_ValidStudent_SavesAndRedirects()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(1, _context.Students.Count());
        var saved = _context.Students.First();
        Assert.Equal("Test", saved.LastName);
        Assert.Equal("User", saved.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), saved.EnrollmentDate);
    }

    [Fact]
    public void CreatePost_DefaultEnrollmentDate_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        Assert.Equal(0, _context.Students.Count());
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsViewWithStudent()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };
        _controller.ModelState.AddModelError("LastName", "Required");

        // Act
        var result = _controller.Create(student);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(0, _context.Students.Count());
    }

    [Fact]
    public void CreatePost_EnrollmentDateBefore1753_AddsModelError()
    {
        // Arrange
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        // Act
        var result = _controller.Create(student);

        // Assert
        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        var errorMessages = _controller.ModelState["EnrollmentDate"].Errors.Select(e => e.ErrorMessage).ToList();
        Assert.Contains(errorMessages, msg => msg.Contains("1753"));
    }

