    [Fact]
    public void EditPost_ValidStudent_UpdatesAndRedirects()
    {
        // Arrange
        var student = SeedStudent("Original", "Name");
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var editedStudent = new Student
        {
            ID = student.ID,
            LastName = "Updated",
            FirstMidName = "Name",
            EnrollmentDate = new DateTime(2024, 1, 1)
        };

        // Act
        var result = _controller.Edit(editedStudent);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void EditPost_DefaultEnrollmentDate_AddsModelError()
    {
        // Arrange
        var student = SeedStudent();
        var editedStudent = new Student
        {
            ID = student.ID,
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = default(DateTime)
        };

        // Act
        var result = _controller.Edit(editedStudent);

        // Assert
        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    // ===== Delete GET Tests =====

    [Fact]
    public void DeleteGet_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteGet_NotFound_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteGet_ValidId_ReturnsViewWithStudent()
    {
        // Arrange
        var student = SeedStudent("Wilson", "Tom");

        // Act
        var result = _controller.Delete(student.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Student>(viewResult.Model);
        Assert.Equal("Wilson", model.LastName);
        Assert.Equal("Tom", model.FirstMidName);
    }

    // ===== DeleteConfirmed Tests =====

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
    {
        // Arrange
        var student = SeedStudent("ToDelete", "Mark");

        // Act
        var result = _controller.DeleteConfirmed(student.ID);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(0, _context.Students.Count());
    }

    [Fact]
    public void DeleteConfirmed_StudentRemoved_NoLongerInDatabase()
    {
        // Arrange
        var student = SeedStudent("Gone", "Student");
        var id = student.ID;

        // Act
        _controller.DeleteConfirmed(id);

        // Assert
        Assert.Null(_context.Students.Find(id));
    }
}

