using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;

namespace ContosoUniversity.Tests;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        _context = TestDbContextFactory.Create(nameof(DepartmentsControllerTests) + Guid.NewGuid());
        _controller = new DepartmentsController(_context);
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor SeedInstructor(string lastName = "Prof", string firstName = "Test")
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = new DateTime(2020, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Department SeedDepartment(string name = "Engineering", Instructor admin = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = 200000,
            StartDate = new DateTime(2020, 9, 1),
            InstructorID = admin?.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_ReturnsViewWithDepartments()
    {
        // Arrange
        SeedDepartment("Math");
        SeedDepartment("English");

        // Act
        var result = _controller.Index();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_IncludesAdministrator()
    {
        // Arrange
        var instructor = SeedInstructor("Admin", "Dept");
        SeedDepartment("CS", instructor);

        // Act
        var result = _controller.Index();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Single(model);
        Assert.NotNull(model[0].Administrator);
        Assert.Equal("Admin", model[0].Administrator.LastName);
    }

    [Fact]
    public void Index_EmptyDb_ReturnsEmptyList()
    {
        // Act
        var result = _controller.Index();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
        Assert.Empty(model);
    }

    // ===== Details Tests =====

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        // Act
        var result = _controller.Details(999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        // Arrange
        var dept = SeedDepartment("Physics");

        // Act
        var result = _controller.Details(dept.DepartmentID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Physics", model.Name);
        Assert.Equal(200000, model.Budget);
    }

    // ===== Create GET Tests =====

    [Fact]
    public void CreateGet_SetsViewBagInstructorID()
    {
        // Arrange
        SeedInstructor();

        // Act
        var result = _controller.Create();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.NotNull(_controller.ViewBag.InstructorID);
        Assert.IsType<SelectList>(_controller.ViewBag.InstructorID);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void CreatePost_ValidDepartment_SavesAndRedirects()
    {
        // Arrange
        var dept = new Department
        {
            Name = "New Dept",
            Budget = 50000,
            StartDate = new DateTime(2024, 1, 1)
        };

        // Act
        var result = _controller.Create(dept);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(1, _context.Departments.Count());
        var saved = _context.Departments.First();
        Assert.Equal("New Dept", saved.Name);
        Assert.Equal(50000, saved.Budget);
    }

    [Fact]
    public void CreatePost_InvalidModelState_ReturnsView()
    {
        // Arrange
        var dept = new Department { Name = "Bad", Budget = 0, StartDate = DateTime.Today };
        _controller.ModelState.AddModelError("Name", "Required");

        // Act
        var result = _controller.Create(dept);

        // Assert
        Assert.IsType<ViewResult>(result);
        Assert.NotNull(_controller.ViewBag.InstructorID);
        Assert.Equal(0, _context.Departments.Count());
    }

    // ===== Edit GET Tests =====

    [Fact]
    public void EditGet_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Edit(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void EditGet_NotFound_ReturnsNotFound()
    {
        // Act
        var result = _controller.Edit(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void EditGet_ValidId_ReturnsViewWithDepartment()
    {
        // Arrange
        var dept = SeedDepartment("Biology");

        // Act
        var result = _controller.Edit(dept.DepartmentID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Biology", model.Name);
        Assert.NotNull(_controller.ViewBag.InstructorID);
    }

    // ===== Edit POST Tests =====

    [Fact]
    public void EditPost_ValidDepartment_UpdatesAndRedirects()
    {
        // Arrange
        var dept = SeedDepartment("Original");
        _context.Entry(dept).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var edited = new Department
        {
            DepartmentID = dept.DepartmentID,
            Name = "Updated",
            Budget = 300000,
            StartDate = new DateTime(2024, 6, 1)
        };

        // Act
        var result = _controller.Edit(edited);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void EditPost_InvalidModelState_ReturnsView()
    {
        // Arrange
        var dept = SeedDepartment("Test");
        _controller.ModelState.AddModelError("Name", "Error");

        // Act
        var result = _controller.Edit(dept);

        // Assert
        Assert.IsType<ViewResult>(result);
        Assert.NotNull(_controller.ViewBag.InstructorID);
    }

    // ===== Delete GET Tests =====

    [Fact]
    public void DeleteGet_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void DeleteGet_NotFound_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void DeleteGet_ValidId_ReturnsViewWithDepartment()
    {
        // Arrange
        var dept = SeedDepartment("Delete Me");

        // Act
        var result = _controller.Delete(dept.DepartmentID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Department>(viewResult.Model);
        Assert.Equal("Delete Me", model.Name);
    }

    // ===== DeleteConfirmed Tests =====

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
    {
        // Arrange
        var dept = SeedDepartment("ToRemove");

        // Act
        var result = _controller.DeleteConfirmed(dept.DepartmentID);

        // Assert
        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Departments.Find(dept.DepartmentID));
    }

    [Fact]
    public void DeleteConfirmed_DepartmentNoLongerInDb()
    {
        // Arrange
        var dept = SeedDepartment("Gone");
        var id = dept.DepartmentID;

        // Act
        _controller.DeleteConfirmed(id);

        // Assert
        Assert.Equal(0, _context.Departments.Count());
    }
}

