using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create(nameof(InstructorsControllerTests) + Guid.NewGuid());
        _controller = new InstructorsController(_context);
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor SeedInstructor(string lastName = "Smith", string firstName = "John",
        DateTime? hireDate = null, string officeLocation = null)
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = hireDate ?? new DateTime(2015, 8, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        if (officeLocation != null)
        {
            instructor.OfficeAssignment = new OfficeAssignment { Location = officeLocation };
        }
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Course SeedCourse(int courseId, string title = "Test Course")
    {
        // Need a department first
        var dept = _context.Departments.FirstOrDefault();
        if (dept == null)
        {
            dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
        }
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    private void SeedInstructorWithCourse(string lastName, int courseId, string courseTitle)
    {
        var course = SeedCourse(courseId, courseTitle);
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = "Test",
            HireDate = new DateTime(2015, 1, 1),
            CourseAssignments = new List<CourseAssignment>
            {
                new CourseAssignment { CourseID = courseId }
            }
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
    }

    // ===== Index Tests =====

    [Fact]
    public void Index_NoSelection_ReturnsInstructorsOnly()
    {
        // Arrange
        SeedInstructor("Adams", "Alice");
        SeedInstructor("Brown", "Bob");

        // Act
        var result = _controller.Index(null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.Equal(2, model.Instructors.Count());
        Assert.Null(model.Courses);
        Assert.Null(model.Enrollments);
    }

    [Fact]
    public void Index_WithInstructorId_ShowsCourses()
    {
        // Arrange
        var course = SeedCourse(100, "Math 101");
        var instructor = new Instructor
        {
            LastName = "Prof",
            FirstMidName = "A",
            HireDate = new DateTime(2015, 1, 1),
            CourseAssignments = new List<CourseAssignment>
            {
                new CourseAssignment { CourseID = 100 }
            }
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        // Act
        var result = _controller.Index(instructor.ID, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Math 101", model.Courses.First().Title);
    }

    [Fact]
    public void Index_OrdersInstructorsByLastName()
    {
        // Arrange
        SeedInstructor("Zeta", "First");
        SeedInstructor("Alpha", "Second");

        // Act
        var result = _controller.Index(null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        var instructors = model.Instructors.ToList();
        Assert.Equal("Alpha", instructors[0].LastName);
        Assert.Equal("Zeta", instructors[1].LastName);
    }

    // ===== Details Tests =====

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        // Act
        var result = _controller.Details(999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructor = SeedInstructor("Jones", "Sarah");

        // Act
        var result = _controller.Details(instructor.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Jones", model.LastName);
        Assert.Equal("Sarah", model.FirstMidName);
        Assert.Equal(instructor.ID, model.ID);
    }

    // ===== Create GET Tests =====

    [Fact]
    public void CreateGet_ReturnsViewWithInstructorAndCourses()
    {
        // Arrange
        SeedCourse(200, "Course A");

        // Act
        var result = _controller.Create();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);
        Assert.NotNull(_controller.ViewBag.Courses);
        var courseData = Assert.IsAssignableFrom<List<AssignedCourseData>>(_controller.ViewBag.Courses);
        Assert.Single(courseData);
        Assert.Equal("Course A", courseData[0].Title);
        Assert.False(courseData[0].Assigned);
    }

    // ===== Create POST Tests =====

    [Fact]
    public void CreatePost_ValidInstructor_SavesAndRedirects()
    {
        // Arrange
        var instructor = new Instructor
        {
            LastName = "New",
            FirstMidName = "Prof",
            HireDate = new DateTime(2024, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
