        var saved = _context.Instructors.First();
        Assert.Equal("New", saved.LastName);
        Assert.Equal("Prof", saved.FirstMidName);
    }

    [Fact]
    public void CreatePost_WithSelectedCourses_AddsCourseAssignments()
    {
        // Arrange
        var course1 = SeedCourse(300, "Course 1");
        var course2 = SeedCourse(301, "Course 2");
        var instructor = new Instructor
        {
            LastName = "Multi",
            FirstMidName = "Course",
