    [Fact]
    public void CreatePost_InvalidModelState_ReturnsViewWithCourseData()
    {
        // Arrange
        SeedCourse(400, "A Course");
        var instructor = new Instructor
        {
            LastName = "Bad",
            FirstMidName = "Data",
            HireDate = DateTime.Today,
            CourseAssignments = new List<CourseAssignment>()
