    [Fact]
    public void SendNotification_EmptyDisplayName_UsesIdFormat()
    {
        // Act
        _sut.SendNotification("Student", "5", "  ", EntityOperation.DELETE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 5", notification.Message);
        Assert.Contains("deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_QueueCapEnforced_OldestDroppedWhenOverMax()
    {
        // The queue cap is 500. Enqueue 502 items, verify the first two are dropped.
        for (int i = 0; i < 502; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE);
        }

        // Dequeue all and collect entity IDs
        var ids = new List<string>();
        Notification n;
        while ((n = _sut.ReceiveNotification()) != null)
        {
            ids.Add(n.EntityId);
        }

        // Should have at most 500 items and the earliest should have been dropped
        Assert.True(ids.Count <= 500, $"Expected at most 500, got {ids.Count}");
        Assert.DoesNotContain("0", ids);
        Assert.DoesNotContain("1", ids);
        Assert.Contains("501", ids);
    }

    [Fact]
    public void SendNotification_IsReadDefaultsFalse()
    {
        // Act
        _sut.SendNotification("X", "1", "Name", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
        Assert.Null(notification.ReadAt);
    }
}

