public void EditPost_ValidStudent_UpdatesAndRedirects()
{
    // Arrange
    var student = SeedStudent("Original", "Name");
    _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

    var editedStudent = new Student
    {
        ID = student.ID,
        LastName = "Updated",
        FirstMidName = "NewFirst",
        EnrollmentDate = new DateTime(2024, 1, 1)
    };

    // Act
    var result = _controller.Edit(editedStudent);

    // Assert
    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);

    // Verify DB state was actually updated
    _context.Entry(editedStudent).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
    var saved = _context.Students.Find(student.ID);
    Assert.Equal("Updated", saved.LastName);
    Assert.Equal("NewFirst", saved.FirstMidName);
    Assert.Equal(new DateTime(2024, 1, 1), saved.EnrollmentDate);
}

